class sequencer_length_extractor #(int unsigned ITEM_WIDTH) extends uvm_logic_vector_array::sequencer #(ITEM_WIDTH);
    `uvm_component_param_utils(uvm_mfb_frame_trimmer::sequencer_length_extractor #(ITEM_WIDTH))

    // Stores the lengths of data frames generated by an RX MFB data sequence
    mailbox #(int unsigned) mfb_item_lengths;

    function new(string name = "sequencer_length_extractor", uvm_component parent = null);
        super.new(name, parent);

        mfb_item_lengths = new();
    endfunction

    task try_next_item(output uvm_logic_vector_array::sequence_item #(ITEM_WIDTH) t);
        super.try_next_item(t);
        if (t === null) begin
            return;
        end
        // Put the data frame length
        mfb_item_lengths.put(t.size());
    endtask

endclass
